#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-1-y] [n-y..n-1] -> [n-y..n-1] [x..n-1-y] [0..x-1]
    vector<int> res;
    for (int i = n-y; i < n; i++) res.push_back(p[i]);
    for (int i = x; i < n-y; i++) res.push_back(p[i]);
    for (int i = 0; i < x; i++) res.push_back(p[i]);
    p = res;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n-2 && (int)ops.size() < 4*n; placed++){
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // Step 1: Move element from pos to position (n-1)
        // We want to make p[pos] the last element
        // Use x = pos+1, y = n-1-pos. But need x+y < n: (pos+1)+(n-1-pos) = n, not < n.
        // So use x = pos+1, y = n-pos-2 (move all but last to rearrange, element goes to some known spot)
        // Actually: to move element at pos to end, set x=pos+1, y=n-1-pos won't work.
        // Alternative: set x=1, y=n-1-pos if pos < n-1. Element at pos moves to pos-1. Not helpful directly.

        // Better: move element to position 0 first, then to target.
        // To move p[pos] to position 0: x = pos, y = n-pos. But x+y = n, invalid.
        // x = pos, y = n-pos-1. Result: [last n-pos-1 elems] [middle=p[pos]] [first pos elems]. Element at position n-pos-1.
        // Hmm. Let me just try: if pos != placed, use two ops.

        if(pos < n-1){
            // Op: x = pos-placed, y = n-1-pos, applied to subproblem... but ops are on whole array.
            // Move element to last position: x=pos+1, y=n-pos-2 if valid
            int x = pos+1, y = n-pos-2;
            if(x > 0 && y > 0 && x+y < n){
                ops.push_back({x,y});
                apply(p,x,y);
                pos = n-2; // element moves to position n-1-1 = n-2... let me recalc
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            }
        }
        if(pos == placed) continue;
        // Now place element: x=placed, y=n-pos if valid, or try other combos
        for(int x=1; x<n && pos!=placed; x++) for(int y=1; x+y<n && pos!=placed; y++){
            vector<int> tp=p; apply(tp,x,y);
            int npos=-1; for(int i=0;i<n;i++) if(tp[i]==placed+1){npos=i;break;}
            if(npos==placed){ops.push_back({x,y}); p=tp; pos=placed;}
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
